/**
 * Bundle topics.json + sources/** into bundle-data.js so index.html works via file://
 * Run after changing sources or topics.json:
 *   node scripts/build-bundle.mjs
 */
import { readFile, writeFile, readdir } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

async function listCsFiles(dir) {
  const out = [];
  const entries = await readdir(dir, { withFileTypes: true });
  for (const e of entries) {
    const full = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...(await listCsFiles(full)));
    else if (e.name.endsWith(".cs")) out.push(full);
  }
  return out;
}

function toPosix(p) {
  return p.split(path.sep).join("/");
}

const topics = JSON.parse(await readFile(path.join(ROOT, "topics.json"), "utf8"));
const sourcesRoot = path.join(ROOT, "sources");
const files = await listCsFiles(sourcesRoot);
const sources = {};

for (const full of files) {
  const rel = toPosix(path.relative(sourcesRoot, full)); // topic/file.cs
  sources[rel] = await readFile(full, "utf8");
}

const payload = { ...topics, sources };
const out = `/* auto-generated by scripts/build-bundle.mjs — do not edit by hand */\nwindow.PORTFOLIO_DATA = ${JSON.stringify(payload)};\n`;
await writeFile(path.join(ROOT, "bundle-data.js"), out, "utf8");
console.log(`bundle-data.js (${(out.length / 1024).toFixed(1)} KB), ${Object.keys(sources).length} sources`);
